INSERT INTO quiz_questions (id, topic_id, question, options, correct, explanation) VALUES
('qz-numsys-1', 'inf-numsys', 'Чему равно двоичное число 1010 в десятичной системе счисления?', ARRAY['8','10','12','20'], ARRAY[1], 'Считаем по разрядам: 1·8 + 0·4 + 1·2 + 0·1 = 10.'),
('qz-numsys-2', 'inf-numsys', 'Сколько различных цифр используется в восьмеричной системе счисления?', ARRAY['7','8','9','16'], ARRAY[1], 'Цифры от 0 до 7 — всего восемь.'),
('qz-numsys-3', 'inf-numsys', 'Какие из чисел могут быть корректной записью в двоичной системе?', ARRAY['101','210','1101','1023'], ARRAY[0,2], 'В двоичной записи допустимы только цифры 0 и 1.'),
('qz-numsys-4', 'inf-numsys', 'Чему равно шестнадцатеричное число 1F в десятичной системе?', ARRAY['15','25','31','33'], ARRAY[2], '1·16 + F (это 15) = 31.'),
('qz-numsys-5', 'inf-numsys', 'Скольким двоичным разрядам соответствует одна шестнадцатеричная цифра?', ARRAY['2','3','4','8'], ARRAY[2], '16 = 2⁴, поэтому одна цифра — это четыре двоичных разряда.'),
('qz-logic-1', 'inf-logic', 'Конъюнкция (И) двух высказываний истинна, когда…', ARRAY['истинно хотя бы одно из них','истинны оба','оба ложны','их значения различны'], ARRAY[1], 'Конъюнкция истинна только при двух истинных операндах.'),
('qz-logic-2', 'inf-logic', 'Чему равно значение выражения ¬0?', ARRAY['0','1','Зависит от контекста','Не определено'], ARRAY[1], 'Инверсия меняет значение на противоположное: ¬0 = 1.'),
('qz-logic-3', 'inf-logic', 'Какие из выражений истинны?', ARRAY['1 ∨ 0','1 ∧ 0','¬0','0 → 1'], ARRAY[0,2,3], 'Ложна только конъюнкция 1 ∧ 0. Остальные истинны.'),
('qz-logic-4', 'inf-logic', 'Импликация A → B ложна, когда…', ARRAY['A=0, B=0','A=0, B=1','A=1, B=0','A=1, B=1'], ARRAY[2], 'Единственный ложный случай — из истины следует ложь.'),
('qz-logic-5', 'inf-logic', 'Сколько строк в таблице истинности выражения с тремя переменными?', ARRAY['3','6','8','9'], ARRAY[2], '2³ = 8 комбинаций значений переменных.'),
('qz-pyvars-1', 'py-vars', 'Что выведет print(type(5))?', ARRAY['<class ''int''>','<class ''float''>','<class ''str''>','5'], ARRAY[0], '5 — целое число, его тип int.'),
('qz-pyvars-2', 'py-vars', 'Какие из значений имеют тип str?', ARRAY['''привет''','5','''5''','True'], ARRAY[0,2], 'Строка — всё, что в кавычках. Даже ''5'' — строка.'),
('qz-pyvars-3', 'py-vars', 'Что вернёт выражение int(''7'') + 1?', ARRAY['71','8','''8''','Ошибку'], ARRAY[1], 'int(''7'') даёт число 7, затем 7 + 1 = 8.'),
('qz-pyvars-4', 'py-vars', 'Функция input() всегда возвращает…', ARRAY['число','строку','логическое значение','список'], ARRAY[1], 'Всё введённое приходит строкой — числа нужно преобразовывать.'),
('qz-pyloops-1', 'py-loops', 'Сколько раз выполнится тело цикла for i in range(5)?', ARRAY['4','5','6','Бесконечно'], ARRAY[1], 'range(5) — это 0,1,2,3,4: пять значений.'),
('qz-pyloops-2', 'py-loops', 'Какие числа перебирает range(2, 6)?', ARRAY['2, 3, 4, 5, 6','2, 3, 4, 5','3, 4, 5, 6','2, 4, 6'], ARRAY[1], 'Левая граница входит, правая — нет.'),
('qz-pyloops-3', 'py-loops', 's = 0; for i in range(3): s = s + 2; print(s). Что выведет?', ARRAY['2','4','6','8'], ARRAY[2], 'Тело выполнится три раза: 0 → 2 → 4 → 6.'),
('qz-pyloops-4', 'py-loops', 'Какие конструкции циклов есть в Python?', ARRAY['for','while','repeat','loop'], ARRAY[0,1], 'В Python два цикла: for и while.');
